<?php global $wpdb; $s=$wpdb->get_results("SELECT id,name_en,name_ar,total_ayahs FROM {$wpdb->prefix}quran_surahs ORDER BY id",ARRAY_A); ?><!doctype html><html><body><main><h1>Surah Archive</h1><?php foreach($s as $x): ?><a href="/single-surah?surah=<?php echo esc_attr((string)$x['id']); ?>"><?php echo esc_html($x['name_en']); ?> (<?php echo esc_html((string)$x['total_ayahs']); ?>)</a><br><?php endforeach; ?></main></body></html>
